/**
 * The rules a world is generated by: what stood scattered through the generator as constants, and what
 * differs between one version of the generator and the next.
 *
 * A world of version 1 is every world made before there were versions, and it stays the same to the bit
 * (harness/sim/world_golden.test.ts is the judge): RULES_V1 is frozen in meaning as well as in value.
 * RULES_V2 is the generator being built in docs/V3/nodes/W1-worldgen.md. The two are separate objects, so
 * that the second can change without the first noticing.
 *
 * The road itself reads this file (spine.ts), so it stands below every other module of the world:
 * whatever it needs at run time — a dealer (dealer.ts), a quiet rule (quiet.ts, director.ts) — may know
 * the road, the landforms, the water and the rest by their types only, never import them to run (the
 * modules would load in a circle). A rule is handed the chapter plan when it is asked, and the plan holds
 * the rules: `plan.rules.slot` is the length of a stretch, `plan.rules.regionCount` how many regions the
 * world knows.
 */
import type { Rng } from '../math/rng';
import { AUTHORED_REGIONS, FIRST_BIOMES, MIN_RADIUS_ANY, handRegions } from './biomes';
import { MAX_BORDER_WIDTH } from './routeProfiles';
import { DEALER_V2 } from './dealer';
import { DEALER_V3 } from './journey/road';
import { DEALER_V4, DEALER_V5 } from './earth/road';
import { quietRun } from './director';
import { quietSlot } from './quiet';
import type { ChapterPlan } from './spine';

/** the versions of the generator there are */
export type WorldVersion = 1 | 2 | 3 | 4 | 5;

/**
 * The revision of the generator of version 2: raised by one whenever a world of version 2 comes out
 * different for the same seed and options (a rule of the dealer, a number of a region, a landform). A save
 * keeps it beside the seed, and a save of another revision is opened by putting the car and the traveller
 * back on the road at the distance they had reached. The reference worlds of version 2 are recorded under
 * it (harness/sim/world-golden.json): a change to version 2 that was not meant shows there. Version 1 has
 * no revisions: it never changes.
 */
export const WORLD_REV = 27;

/** one chapter as its dealer hands it over */
export interface DealtChapter {
  /** the region the chapter runs through: an index into BIOMES, below the world's `regionCount` (version 4: or one of the emergent Earth's, biomes.ts earthRegion) */
  region: number;
  /** the chapter's length along the road (m) */
  length: number;
  /**
   * The width of the blend at its start (m, the chapters' scale reckoned in): version 3's, its journey's join
   * (journey/road.ts); absent, the corridors' between the two regions (version 2), or the world's one width (version 1).
   */
  border?: number;
}

/**
 * What a dealer is told when it deals: the world's identity and the chapters dealt so far — nothing of
 * the road's geometry, which is laid only after it (the road reads the chapters, never the other way).
 */
export interface DealerView {
  /** the world's seed */
  readonly seed: number;
  /** what chapter lengths are multiplied by (SpineOptions.chapterScale) */
  readonly scale: number;
  /** the region the journey was asked to begin in (SpineOptions.startBiome as an index into BIOMES; 0 when it named none the world knows) */
  readonly startRegion: number;
  /** the world's rules: `regionCount` (never deal an index at or above it), `slot`, `version` */
  readonly rules: WorldRules;
  /** the regions dealt so far, chapter by chapter (empty while chapter 0 is being dealt) */
  readonly regions: readonly number[];
  /** where each chapter begins (m of road): one entry more than `regions`, the last being where the chapter now dealt begins */
  readonly starts: readonly number[];
  /**
   * The chapter plan's own stream of dice, Rng(hash2(seed, 0xb10e, 77)). Version 1 draws from it in
   * order, one number for chapter 0 and two for every chapter after; a dealer that takes its dice from
   * hashes of the chapter's index instead never touches it.
   */
  readonly rng: Rng;
}

/** Who decides which region comes next and how long it lasts. Without state of its own: one dealer serves every world of its version. */
export interface ChapterDealer {
  /** chapter 0 */
  first(deal: DealerView): DealtChapter;
  /** the chapter after those dealt so far (its index is `deal.regions.length`) */
  next(deal: DealerView): DealtChapter;
}

/**
 * Is stretch k of the road one of the journey's quiet ones (no place to stop, no lake, no bridge, no
 * colossal remain)? Decided from dice and the chapter plan alone, so that the water, the places and the
 * landmarks all agree, whoever asks first.
 */
export type QuietRule = (plan: ChapterPlan, seed: number, k: number) => boolean;

/** what keeps the road a road: x always increasing along it, no curve the meshes cannot follow, no grade a loaded car cannot climb */
export interface RoadRules {
  /**
   * Heading guards, in degrees either side of +x: from 0 to `headingSoft` a new curve is ever more
   * likely to turn back towards +x; no curve is planned to carry the heading beyond `headingLimit`, and
   * one with less than `headingRoom` of room left on its side turns the other way; a curve that would
   * still unwind beyond `headingHard` is met with a counter-curve.
   */
  readonly headingSoft: number;
  readonly headingLimit: number;
  readonly headingRoom: number;
  readonly headingHard: number;
  /** no curve is tighter than this, whatever a region's design speed says (m) */
  readonly radiusFloor: number;
  /** no grade is steeper than this, whatever a region's own limit says (rise per metre) */
  readonly gradeCap: number;
  /**
   * How the road drifts back to its country's base elevation: a grade of the difference over `pullLen` m, but
   * never more than `pull` (rise per metre), added to the grade it would take anyway (the region's own climbs).
   */
  readonly pull: number;
  readonly pullLen: number;
  /**
   * Where the base elevation comes from: version 1 mixes the two regions' baseElev over the border between
   * them; version 2 takes each region's RegionRelief.base, blended over kilometres (relief.ts baseAt).
   */
  readonly longBase: boolean;
}

export interface WorldRules {
  readonly version: WorldVersion;
  /**
   * How many entries of the region registry (biomes.ts BIOMES) this world knows. Regions are only ever
   * appended to the registry, so a world keeps its count and never sees the ones that came after it.
   */
  readonly regionCount: number;
  /**
   * Metres of road per stretch: landforms, water, places and quiet stretches are all laid out on this
   * one grid (the plans' own constants LAND_SLOT, WATER_SLOT and SITE_SLOT must equal it: terrain.ts
   * checks when a world is made).
   */
  readonly slot: number;
  /** who deals the chapters */
  readonly dealer: ChapterDealer;
  /** the length over which two regions blend into each other at a chapter border (m), by chapter scale */
  readonly transition: (scale: number) => number;
  /** which stretches are left quiet */
  readonly quiet: QuietRule;
  readonly road: RoadRules;
}

/** the kinds of country version 1 deals from once a journey is under way: the six there were when it was written */
const V1_REGIONS = 6;

/**
 * Version 1's dealer, draw for draw what the chapter plan always did. The pools are written as numbers
 * — three kinds, then six — and never as the registry's length: that is what lets a region be appended
 * to the registry without a single old world changing.
 */
export const DEALER_V1: ChapterDealer = {
  first(deal) {
    // the first chapter is a short, gentle introduction
    return { region: deal.startRegion, length: deal.rng.range(6000, 9000) * deal.scale };
  },
  next(deal) {
    const c = deal.regions.length;
    const prev = deal.regions[c - 1];
    // The first four chapters are drawn from the three kinds of country the journey begins in (and
    // drawn exactly as they always were: one number, the other two in order); from the fifth on every
    // kind may come, never the one just left nor the one before it.
    const before = c >= 2 ? deal.regions[c - 2] : -1;
    const kinds = Math.min(c < 4 ? FIRST_BIOMES : V1_REGIONS, deal.rules.regionCount);
    const pool: number[] = [];
    for (let b = 0; b < kinds; b++) if (b !== prev && (c < 4 || b !== before)) pool.push(b);
    const region = pool[deal.rng.int(pool.length)];
    return { region, length: deal.rng.range(10000, 18000) * deal.scale };
  },
};

const ROAD_V1: RoadRules = Object.freeze({ headingSoft: 40, headingLimit: 44, headingRoom: 8, headingHard: 49, radiusFloor: MIN_RADIUS_ANY, gradeCap: 0.08, pull: 0.035, pullLen: 2500, longBase: false });

/** Version 1: every world made before there were versions. Nothing here may change. */
export const RULES_V1: WorldRules = Object.freeze({
  version: 1,
  regionCount: V1_REGIONS,
  slot: 1250,
  dealer: DEALER_V1,
  transition: (scale: number): number => Math.max(300, 900 * Math.min(1, scale * 2)),
  // two neighbouring stretches in every block of nine, from the fourth chapter on (quiet.ts)
  quiet: quietSlot,
  road: ROAD_V1,
});

/**
 * Version 2 (docs/V3/nodes/W1-worldgen.md): regions dealt for a gentle journey with tension and release,
 * each a whole number of stretches (dealer.ts), and one quiet run of two stretches to a region
 * (director.ts). The road's guards and the transition are version 1's values, written out again rather
 * than shared, so that changing one here never reaches a version 1 world. Its region count is the whole
 * registry at the time a world is made (`rulesFor`); the number here is only what it was when this file
 * was loaded. Whatever changes what a world of this version looks like raises WORLD_REV.
 */
export const RULES_V2: WorldRules = Object.freeze({
  version: 2,
  regionCount: AUTHORED_REGIONS,
  slot: 1250,
  dealer: DEALER_V2,
  transition: (scale: number): number => MAX_BORDER_WIDTH * Math.max(0.1, Math.min(1, scale)),
  quiet: quietRun,
  // (the road climbs into high country at up to five in a hundred above its own climbs, and begins kilometres
  // before the country does: stage L1's mountain valleys stand a kilometre above the sea)
  road: Object.freeze({ headingSoft: 40, headingLimit: 44, headingRoom: 8, headingHard: 49, radiusFloor: MIN_RADIUS_ANY, gradeCap: 0.08, pull: 0.05, pullLen: 2000, longBase: true }),
});

/**
 * Version 3 (docs/V3/nodes/P3-1-journey-world.md): version 2's generator with the journey for its dealer — the
 * fifty scenic roads shuffled, the joins between them, a scene drawn as its nearest region until its own is
 * made (journey/road.ts). Everything else is version 2's, its road's guards too: a change to version 2 changes
 * version 3 with it (WORLD_REV is the two's), and nothing here changes version 2.
 */
export const RULES_V3: WorldRules = Object.freeze({
  ...RULES_V2,
  version: 3,
  dealer: DEALER_V3,
});

/**
 * Version 4 (docs/V3/nodes/E1-earth-world.md): the emergent Earth — version 2's generator with the director of
 * core/earth for its dealer: home first (the region the world was asked to begin in), then one chapter to each of
 * the director's places, five kilometres of road, each a region of its own made from the place (earth/region.ts,
 * put in the registry as the journey reaches it: biomes.ts earthRegion). It knows the regions written by hand as
 * versions 2 and 3 do, and deals the Earth's besides.
 */
export const RULES_V4: WorldRules = Object.freeze({
  ...RULES_V2,
  version: 4,
  dealer: DEALER_V4,
  // (its road climbs as the director's do — over a range at five to seven and a half in a hundred (core/earth/director.ts
  // GRADE) — and so is drawn to its country's height harder than version 2's, within the same cap)
  road: Object.freeze({ ...RULES_V2.road, pull: 0.07, pullLen: 1500 }),
});

/**
 * Version 5 (docs/V3/plan/scenic-roads.md, docs/V3/nodes/R2-roads.md): the emergent Earth's scenic roads — version
 * 4's journey with a sense of drama (the lowlands never run on for long) and the director of the roads (core/earth/
 * roads.ts), each place driven by a road of its own kind (a shelf over a valley, a skyline drive, a gorge, a cliff
 * road over the sea, a tunnel of trees, the grassland's swell …), the places blending over a third of a chapter
 * where version 4's blend over most of it. Version 4's world is untouched: its saves are the same world.
 */
export const RULES_V5: WorldRules = Object.freeze({
  ...RULES_V4,
  version: 5,
  dealer: DEALER_V5,
});

/**
 * The rules of a world: its version's, with its own region count. Without a count a world of version 1
 * knows the six regions there were when version 1 was closed, and a world of version 2 every region
 * registered when it is made — which is why a save must keep the count (WorldOptions.regionCount).
 */
export function rulesFor(version: WorldVersion = 1, opts: { regionCount?: number } = {}): WorldRules {
  if (version !== 1 && version !== 2 && version !== 3 && version !== 4 && version !== 5) throw new RangeError(`world version ${String(version)}: there are versions 1, 2, 3, 4 and 5`);
  const base = version === 5 ? RULES_V5 : version === 4 ? RULES_V4 : version === 3 ? RULES_V3 : version === 2 ? RULES_V2 : RULES_V1;
  // (the regions written by hand: the emergent Earth's, after them in the registry, are no world's to count)
  const hand = handRegions();
  const count = opts.regionCount ?? (version >= 2 ? hand : V1_REGIONS);
  // (at least the three kinds every journey begins in; at most what the registry holds)
  if (!Number.isInteger(count) || count < FIRST_BIOMES || count > hand) {
    throw new RangeError(`regionCount ${String(count)}: a world knows between ${FIRST_BIOMES} regions and all ${hand} of the registry written by hand`);
  }
  return count === base.regionCount ? base : Object.freeze({ ...base, regionCount: count });
}
